"""Build the project handover PDF. No credentials or user records are read."""
from pathlib import Path
from html import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, Preformatted
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4

OUT = Path('output/pdf')
OUT.mkdir(parents=True, exist_ok=True)
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='Body', fontName='Helvetica', fontSize=10, leading=15, spaceAfter=9, textColor=colors.HexColor('#253747')))
styles.add(ParagraphStyle(name='Section', fontName='Helvetica-Bold', fontSize=23, leading=28, spaceAfter=18, textColor=colors.HexColor('#103c50')))
styles.add(ParagraphStyle(name='Sub', fontName='Helvetica-Bold', fontSize=12, leading=17, spaceBefore=10, spaceAfter=6, textColor=colors.HexColor('#17715d')))
styles.add(ParagraphStyle(name='CodeSmall', fontName='Courier', fontSize=8, leading=11, spaceBefore=6, spaceAfter=12, backColor=colors.HexColor('#edf3f5'), borderPadding=9))
styles.add(ParagraphStyle(name='Cell', fontName='Helvetica', fontSize=9, leading=12, textColor=colors.HexColor('#253747')))
story = []
sections = []

def p(text): story.append(Paragraph(text, styles['Body']))
def h(text): story.append(Paragraph(text, styles['Sub']))
def step(n, title, text): p(f'<b>{n}. {title}</b><br/>{text}')
def code(text): story.append(Preformatted(text.strip('\n'), styles['CodeSmall']))
def table(rows, widths=None):
    data = [[Paragraph(escape(str(cell)), styles['Cell']) for cell in row] for row in rows]
    t = Table(data, colWidths=widths or [150, 345], hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dcebe7')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,0),(-1,-1),0.4,colors.HexColor('#d9e2e6'))]))
    story.append(t); story.append(Spacer(1,10))
def page(title, kicker='PROJECT HANDBOOK'):
    if story: story.append(PageBreak())
    sections.append(title)
    p(f'<font size="9" color="#17715d"><b>{kicker}</b></font>')
    story.append(Paragraph(title, styles['Section']))

page('D.I. Recruitment<br/>Web Application', 'TECHNICAL DOCUMENTATION / OWNER HANDBOOK')
story.append(Spacer(1,28))
p('<font size="17">From the first setup to daily administration,<br/>deployment, and a PostgreSQL migration.</font>')
story.append(Spacer(1,28))
